#!/bin/bash
# Real-WordPress end-to-end check for the standalone plugin and the plugin generated by
# `w2agent integrate --platform wordpress --install`.
# Needs Docker and a built repo (`pnpm build`). Usage: bash packages/wordpress/tests/e2e/run.sh
# Exits non-zero on any FAIL or PRECONDITION-FAILED line.
set -u -o pipefail

E2E_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO=$(cd "$E2E_DIR/../../../.." && pwd)
CLI=$REPO/packages/cli/dist/index.js
CORE=$REPO/packages/core/dist/index.js
STANDALONE=${W2AGENT_E2E_STANDALONE:-$REPO/packages/wordpress/w2agent-plugin.php} # override: run the E2E against another copy

RUN_ID=${W2AGENT_E2E_RUN_ID:-$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')} # the override exists for the collision repro
WORK=$(mktemp -d "${TMPDIR:-/tmp}/w2agent-e2e.XXXXXX") || exit 1
WORK=$(cd "$WORK" && pwd -P)

# shellcheck source=lib.sh
. "$E2E_DIR/lib.sh"
trap cleanup EXIT
trap 'exit 130' INT TERM

command -v docker >/dev/null || { echo "PRECONDITION-FAILED docker not found"; exit 1; }
docker info >/dev/null 2>&1 || { echo "PRECONDITION-FAILED docker daemon not reachable"; exit 1; }
[ -f "$CLI" ] && [ -f "$CORE" ] || { echo "PRECONDITION-FAILED run pnpm build first (packages/cli/dist, packages/core/dist)"; exit 1; }
[ -f "$STANDALONE" ] || { echo "PRECONDITION-FAILED standalone plugin missing"; exit 1; }

# shellcheck source=checks-cache.sh
. "$E2E_DIR/checks-cache.sh"
# shellcheck source=checks-sub-ms.sh
. "$E2E_DIR/checks-sub-ms.sh"

RP=$(free_port 18080)
SP=$(free_port $((RP + 1)))
MP=$(free_port $((SP + 1)))
R=root
SITE=$(site_dir "$R")
GEN_DIR=$SITE/wp-content/plugins/w2agent-site
SA_DIR=$SITE/wp-content/plugins/w2agent
B=http://localhost:$RP

echo "=== start root site on port $RP"
up "$R" "$RP" || exit 1
cp "$E2E_DIR/seed.php" "$SITE/w2a-seed.php"
wpc "$R" eval-file /var/www/html/w2a-seed.php

echo "=== standalone plugin alone, in its documented folder w2agent/"
mkdir -p "$SA_DIR"
cp "$STANDALONE" "$SA_DIR/"
wpc "$R" plugin activate w2agent >/dev/null 2>&1
SL=$(curl -s "$B/llms.txt")
chk "standalone alone serves /llms.txt" '[ "$(curl -s -o /dev/null -w "%{http_code}" "$B/llms.txt")" = 200 ]'
chk "WP-7 standalone alone 404s /llms-full.txt" '[ "$(curl -s -o /dev/null -w "%{http_code}" "$B/llms-full.txt")" = 404 ]'
chk "WP-3 standalone: no password content" '! grep -q SECRET <<<"$SL"'
chk "WP-4 standalone: newest post listed" 'grep -q "Newest post marker" <<<"$SL"'
chk "WP-3 standalone: no builder template" '! grep -q "Header template" <<<"$SL"'
cache_context "$RP" w2agent w2agent_llms_txt
wpc "$R" plugin activate w2agent >/dev/null 2>&1

echo "=== integrate --install through the built CLI (standalone present)"
node "$CLI" integrate "$B" --platform wordpress --install --project-dir "$SITE" --max-pages 15 \
  --a2a-endpoint "$B/a2a" >"$WORK/integrate.log" 2>&1
INT_RC=$?
chk "integrate --install exits 0" '[ "$INT_RC" = 0 ]'
[ "$INT_RC" = 0 ] || sed -n '1,30p' "$WORK/integrate.log"
chk "integrate wrote w2agent-site/w2agent-plugin.php" '[ -f "$GEN_DIR/w2agent-plugin.php" ]'
chk "integrate left the standalone folder untouched" '[ "$(ls "$SA_DIR")" = w2agent-plugin.php ]'
chk "integrate wrote w2agent-webmcp.php" '[ -f "$GEN_DIR/w2agent-webmcp.php" ]'

echo "=== both plugins active"
wpc "$R" plugin activate w2agent-site >/dev/null 2>&1
H=$(curl -s "$B/")
chk "WP-10 one discovery link tag" '[ "$(grep -o "type=\"text/markdown\"" <<<"$H" | wc -l | tr -d " ")" = 1 ]'
chk "WP-10 robots.txt mentions llms.txt at most once" '[ "$(curl -s "$B/robots.txt" | grep -c "llms.txt" || true)" -le 1 ]'
. "$E2E_DIR/checks-root.sh"
cache_context "$RP" w2agent-site w2agent_site_llms_txt
wpc "$R" plugin activate w2agent w2agent-site >/dev/null 2>&1

echo "=== WP-10 activation orders"
WPLOG=$SITE/wp-content/debug.log
pre "debug.log works (log probe)" 'curl -s -o /dev/null "$B/?w2a_log_probe=1"; grep -q "w2a-e2e log probe" "$WPLOG"'
for ORDER in "w2agent w2agent-site" "w2agent-site w2agent"; do
  wpc "$R" plugin deactivate w2agent w2agent-site >/dev/null 2>&1
  OUT=""
  for P in $ORDER; do OUT="$OUT$(wpc "$R" plugin activate "$P" 2>&1)"; done
  chk "WP-10 [$ORDER] activation output has no fatal" '! grep -qi "fatal\|parse error" <<<"$OUT"'
  chk "WP-10 [$ORDER] both plugins active" '[ "$(wpc "$R" plugin list --status=active --fields=name 2>/dev/null | grep -c "^w2agent")" = 2 ]'
  BODY=$(curl -s "$B/llms.txt")
  chk "WP-10 [$ORDER] exactly one llms.txt body" '[ "$(grep -c "^# " <<<"$BODY")" = 1 ] && [ "$(grep -c "Newest post marker" <<<"$BODY")" = 1 ]'
  H=$(curl -s "$B/")
  chk "WP-10 [$ORDER] one discovery link tag" '[ "$(grep -o "type=\"text/markdown\"" <<<"$H" | wc -l | tr -d " ")" = 1 ]'
  chk "WP-2 [$ORDER] webmcp script present" 'grep -q modelContext <<<"$H"'
done
chk "WP-10 no fatal in debug.log" '! grep -qi "fatal" "$WPLOG"'
chk "WP-10 no w2agent warning or notice in debug.log" '[ "$(grep -i "w2agent" "$WPLOG" | grep -cE "Warning|Notice|Deprecated" || true)" = 0 ]'
chk "WP-10 no PHP fatal in the Apache log" '! docker logs "$PREFIX-wp-$R" 2>&1 | grep -q "PHP Fatal"'

. "$E2E_DIR/checks-robots.sh"
robots_checks

echo "=== WP-9 webhook hooks"
wpc "$R" option update w2agent_api_key k >/dev/null
wpc "$R" option update w2agent_webhook_slug sa >/dev/null
node "$E2E_DIR/gen-webhook.mjs" "$CORE" "$WORK/webhook-generated.php" >/dev/null
sed -e 's#YOUR_SLUG#gen#g' -e 's#YOUR_WEBHOOK_TOKEN#tok#g' "$WORK/webhook-generated.php" >"$GEN_DIR/w2agent-mcp-webhook.php"
pre "configured webhook file installed in w2agent-site/" '[ -s "$GEN_DIR/w2agent-mcp-webhook.php" ] && grep -q "webhook/gen" "$GEN_DIR/w2agent-mcp-webhook.php"'
cp "$GEN_DIR/w2agent-mcp-webhook.php" "$WORK/webhook-configured.php"
. "$E2E_DIR/checks-hooks.sh"

echo "--- a copy pasted into functions.php (mu-plugin here) next to the loaded file"
cp "$GEN_DIR/w2agent-mcp-webhook.php" "$SITE/wp-content/mu-plugins/w2a-pasted-webhook.php"
reset_log
PASTE_OUT=$(wpc "$R" post create --post_status=publish --post_title=PasteProbe 2>&1)
chk "WP-9 pasted copy does not redeclare or fatal" '! grep -qi "fatal\|cannot redeclare" <<<"$PASTE_OUT"'
chk "WP-9 pasted copy plus loaded file send one request (got $(count "webhook/gen "))" '[ "$(count "webhook/gen ")" = 1 ]'
docker exec "$PREFIX-wp-$R" rm -f /var/www/html/wp-content/mu-plugins/w2a-pasted-webhook.php

echo "--- placeholders left in"
cp "$WORK/webhook-generated.php" "$GEN_DIR/w2agent-mcp-webhook.php"
reset_log
wpc "$R" post create --post_status=publish --post_title=PlaceholderProbe >/dev/null 2>&1
chk "WP-9 placeholder copy sends nothing to YOUR_SLUG" '[ "$(count YOUR_SLUG)" = 0 ]'
chk "WP-9 placeholder copy sends no generated-plugin request" '[ "$(count "webhook/gen ")" = 0 ]'
chk "WP-9 the standalone still notifies while the generated copy is unconfigured" '[ "$(count "webhook/sa ")" = 1 ]'

echo "--- placeholder file in w2agent-site/ plus a configured copy in the active theme's functions.php"
THEME=$(wpc "$R" theme list --status=active --field=name 2>/dev/null | head -1)
FN=$SITE/wp-content/themes/$THEME/functions.php
pre "active theme has a functions.php that never leaves PHP mode" '[ -f "$FN" ] && ! grep -q "?>" "$FN"'
cp "$FN" "$WORK/functions.bak"
tail -n +2 "$WORK/webhook-configured.php" >>"$FN"
reset_log
wpc "$R" post create --post_status=publish --post_title=ThemeCopyProbe >/dev/null 2>&1
chk "R1 configured copy in functions.php wins over the placeholder file (got $(count "webhook/gen ") request(s))" '[ "$(count "webhook/gen ")" = 1 ]'
chk "R1 nothing goes to YOUR_SLUG" '[ "$(count YOUR_SLUG)" = 0 ]'
cp "$WORK/functions.bak" "$FN"

echo "=== subdirectory and multisite"
SUB=sub
MS=ms
up "$SUB" "$SP" || exit 1
up "$MS" "$MP" || exit 1
sub_checks "$SUB" "$SP"
ms_checks "$MS" "$MP"

echo "=== seed fallback (destructive, last)"
. "$E2E_DIR/checks-seed.sh"

echo "=== php -l under PHP 7.4 and 8.3"
for V in 7.4 8.3; do
  for F in "$GEN_DIR"/*.php "$WORK/webhook-generated.php" "$STANDALONE"; do
    D=$(dirname "$F")
    BASE=$(basename "$F")
    RES=$(docker run --rm --cidfile "$CIDDIR/phplint-$(rand_id)" -v "$D:/w:ro" "php:$V-cli-alpine" php -l "/w/$BASE" 2>&1 | head -1)
    chk "php -l $V $BASE: $RES" 'grep -q "^No syntax errors" <<<"$RES"'
  done
done

echo "=== E2E SUMMARY: $PASSES passed, $FAILS failed"
[ "$FAILS" = 0 ]
